import{_ as e,o as t,c as a,ag as r}from"./chunks/framework.KxDd3USm.js";const _=JSON.parse('{"title":"01.7 案例题专攻：算法填空解题套路","description":"","frontmatter":{},"headers":[],"relativePath":"01-数据结构与算法/07-案例题专攻.md","filePath":"01-数据结构与算法/07-案例题专攻.md"}'),d={name:"01-数据结构与算法/07-案例题专攻.md"};function i(n,o,c,l,s,g){return t(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="_01-7-案例题专攻-算法填空解题套路" tabindex="-1">01.7 案例题专攻：算法填空解题套路 <a class="header-anchor" href="#_01-7-案例题专攻-算法填空解题套路" aria-label="Permalink to &quot;01.7 案例题专攻：算法填空解题套路&quot;">​</a></h1><p>案例第 4 题一般是「一段说明 + C 代码（或伪代码）+ 3～5 个空 + 1 小问」，常考：动态规划、贪心、回溯、字符串处理、链表/树操作。<strong>套路如下：</strong></p><h3 id="套路一-先读说明再读代码-说明就是答案说明书" tabindex="-1">套路一：先读说明再读代码，说明就是答案说明书 <a class="header-anchor" href="#套路一-先读说明再读代码-说明就是答案说明书" aria-label="Permalink to &quot;套路一：先读说明再读代码，说明就是答案说明书&quot;">​</a></h3><p>题干「说明」部分会用文字描述算法步骤，例如&quot;第 3 步：若 a[i] 大于当前最大值，则更新最大值&quot;。<strong>空基本就藏在文字步骤对应的代码行上，照着文字填代码。</strong></p><h3 id="套路二-看空的位置判断要填什么" tabindex="-1">套路二：看空的位置判断要填什么 <a class="header-anchor" href="#套路二-看空的位置判断要填什么" aria-label="Permalink to &quot;套路二：看空的位置判断要填什么&quot;">​</a></h3><ol><li><strong>空在初始化处</strong>：常填 <code>0</code>、<code>1</code>、<code>-1</code>、<code>INT_MAX</code> 或数组首元素 <code>a[0]</code>。</li><li><strong>空在循环条件</strong>：看循环变量和边界，<code>i &lt; n</code>、<code>j &gt; 0</code>，或动态规划的 <code>i &lt;= n</code>。</li><li><strong>空在 if 内部更新处</strong>：动态规划常填递推式 <code>dp[i] = dp[i-1] + xxx</code>；求最大值常填 <code>maxv = a[i]</code>。</li><li><strong>空在递归调用</strong>：填递归式，参数看函数定义对应着填，注意返回值 <code>return f(...)</code>。</li><li><strong>空在 return</strong>：动态规划常填 <code>dp[n]</code> 或 <code>dp[m][n]</code>。</li></ol><h3 id="套路三-代入一个具体例子验证" tabindex="-1">套路三：代入一个具体例子验证 <a class="header-anchor" href="#套路三-代入一个具体例子验证" aria-label="Permalink to &quot;套路三：代入一个具体例子验证&quot;">​</a></h3><p>填完后，用一个 n=2 或 n=3 的小例子手动模拟整段代码，能跑通且结果符合说明，基本就对了。</p><h3 id="常见考题模板速记" tabindex="-1">常见考题模板速记 <a class="header-anchor" href="#常见考题模板速记" aria-label="Permalink to &quot;常见考题模板速记&quot;">​</a></h3><ul><li><strong>0-1 背包</strong>：<code>dp[i][j] = max(dp[i-1][j], dp[i-1][j-w[i]] + v[i])</code>，j 从大到小滚动数组。</li><li><strong>最长公共子序列</strong>：字符相等 <code>dp[i][j]=dp[i-1][j-1]+1</code>，否则 <code>max(dp[i-1][j], dp[i][j-1])</code>。</li><li><strong>Fibonacci / 爬楼梯</strong>：<code>f[i] = f[i-1] + f[i-2]</code>。</li><li><strong>链表插入</strong>：<code>s-&gt;next = p-&gt;next; p-&gt;next = s;</code>（顺序不能反）。</li><li><strong>链表删除</strong>：<code>p-&gt;next = p-&gt;next-&gt;next;</code>。</li><li><strong>二叉树递归遍历</strong>：<code>visit(root); f(root-&gt;left); f(root-&gt;right);</code> 按序对应前中后序。</li></ul><hr>',11)])])}const h=e(d,[["render",i]]);export{_ as __pageData,h as default};
